require_once __DIR__.'/../api-auth.php';require_once __DIR__.'/../../../includes/student-communication-api.php';requireApiMethod('POST');$student=requireApiStudent($pdo);$userId=(int)$student['user_id'];$communication=studentVisibleCommunication($pdo,trim((string)($_GET['uuid']??'')),$userId);if(!$communication)apiResponse(false,'Communication introuvable.',[],404);
try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id FROM destinataires_communications WHERE communication_officielle_id=? AND utilisateur_id=? ORDER BY id LIMIT 1 FOR UPDATE');$q->execute([$communication['id'],$userId]);$recipientId=(int)$q->fetchColumn();if(!$recipientId){$pdo->prepare("INSERT INTO destinataires_communications(communication_officielle_id,utilisateur_id,statut_remise,remise_le) VALUES(?,?,'remise',UTC_TIMESTAMP(6))")->execute([$communication['id'],$userId]);$recipientId=(int)$pdo->lastInsertId();}$pdo->prepare("UPDATE destinataires_communications d JOIN communications_officielles c ON c.id=d.communication_officielle_id SET d.lue_le=COALESCE(d.lue_le,UTC_TIMESTAMP(6)),d.accusee_le=CASE WHEN c.accuse_reception_requis=1 THEN COALESCE(d.accusee_le,UTC_TIMESTAMP(6)) ELSE d.accusee_le END WHERE d.id=?")->execute([$recipientId]);$pdo->commit();apiResponse(true,'Lecture enregistree.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[API COMMUNICATION READ] '.$e->getMessage());apiResponse(false,'Impossible d enregistrer la lecture.',[],500);}
